use vstd::prelude::*;

verus! {
    // Reverse a vector of i8s.
    // Ensures that the result has the same length as the input,
    // and for each index k in [0, n), rev[k] == s[n-1-k].
    fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
        ensures
            rev.len() == s.len(),
            forall |k: usize| k < s.len() ==> rev[k] == s[s.len() - 1 - k],
    {
        let n = s.len();
        let mut rev: Vec<i8> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                rev.len() == i,
                // Invariant: for all indices less than i,
                // rev[k] == s[n-1-k].
                forall |k: usize| k < i ==> rev[k] == s[n - 1 - k],
            decreases n - i,
        {
            let x = s[n - 1 - i];
            rev.push(x);
            i = i + 1;
        }
        rev
    }
}

